static unsigned hf(char*s){unsigned h=5381;while(*s)h=h*33+(unsigned char)*s++;return h&(HS-1);}
static int hg(char*s){unsigned i=hf(s);while(hk[i]){if(!strcmp(hk[i],s))return hv[i];i=(i+1)&(HS-1);}return -1;}
static int cl(int c){return !c||c==32||(c>8&&c<14)?0:c>47&&c<58?2:(c>96&&c<123)||(c>64&&c<91)||c>127?1:3;}
static void ln(float*d,float*s,float*g,float*b){int i;double m=0,v=0,t;for(i=0;i<D;i++)m+=s[i];m/=D;for(i=0;i<D;i++){t=s[i]-m;v+=t*t;}v=1/sqrt(v/D+1e-5);for(i=0;i<D;i++)d[i]=(s[i]-m)*v*g[i]+b[i];}
static void mv(float*y,float*s,float*w,float*b,int nr,int nc){int i,j;float u,*p;for(j=0;j<nc;j++)y[j]=b[j];for(i=0;i<nr;i++){u=s[i];p=w+(long)i*nc;for(j=0;j<nc;j++)y[j]+=u*p[j];}}
static void enc(unsigned char*s,int n){int m=0,i,r,b,bi;
 for(i=0;i<n&&m<4000;i++){sd[m]=bm[s[i]];sy[m]=vs[sd[m]];m++;}
