 for(i=0;i<m;i++)if(nt<C)tk[nt++]=sd[i];}
static int fwd(int t,int pos,int last){int l,h,i,j;float*B,*k,*v,mx,sm,u,d;
 for(i=0;i<D;i++)x[i]=W[85842432L+(long)t*D+i]+W[85056000L+pos*D+i];
