 if(!last)return 0;
 ln(t1,x,W+85055232,W+85054464);
 j=0;mx=-1e30;
 for(i=0;i<50257;i++){d=0;k=W+85842432L+(long)i*D;for(h=0;h<D;h++)d+=t1[h]*k[h];if(d>mx){mx=d;j=i;}}
 return j;}
static void pr(int t){unsigned char*s=(unsigned char*)vs[t],c;while(*s){if(*s<128)c=rv[*s++];else{c=rv[(*s&31)<<6|(s[1]&63)];s+=2;}putchar(c);}}
